using System.Data;
using System.Security.Cryptography;
using System.Text;
using ahis.template.identity.Contexts;
using ahis.template.identity.Interfaces;
using ahis.template.identity.Models.DTOs;
using ahis.template.identity.Models.Entities;
using ahis.template.identity.Security;
using FluentResults;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace ahis.template.identity.Services;

public sealed class IdentityRoleManagementService : IIdentityRoleManagementService
{
    private static readonly string[] ProtectedRoles = [IdentityRoleNames.Superadmin, IdentityRoleNames.User];
    private readonly IdentityContext _context; private readonly RoleManager<IdentityRole> _roles; private readonly UserManager<ApplicationUser> _users;
    private readonly ILookupNormalizer _normalizer; private readonly IAccountSecurityProofService _proof; private readonly IIdentityTokenStateService _tokens; private readonly IIdentityRestrictionService _restrictions;
    public IdentityRoleManagementService(IdentityContext context, RoleManager<IdentityRole> roles, UserManager<ApplicationUser> users, ILookupNormalizer normalizer, IAccountSecurityProofService proof, IIdentityTokenStateService tokens, IIdentityRestrictionService restrictions)
    { _context=context; _roles=roles; _users=users; _normalizer=normalizer; _proof=proof; _tokens=tokens; _restrictions=restrictions; }

    public async Task<Result<IdentityRolePageDto<IdentityRoleListItemDto>>> GetRolesAsync(string? name,int pageNumber,int pageSize,CancellationToken ct)
    { var q=_context.Roles.AsNoTracking(); var filter=_normalizer.NormalizeName(name?.Trim() ?? string.Empty); if(!string.IsNullOrEmpty(filter)) q=q.Where(r=>r.NormalizedName!.StartsWith(filter)); var total=await q.CountAsync(ct); var rows=await q.OrderBy(r=>r.NormalizedName).ThenBy(r=>r.Id).Skip((pageNumber-1)*pageSize).Take(pageSize).Select(r=>new {r.Id,r.Name, Count=_context.UserRoles.Count(x=>x.RoleId==r.Id)}).ToListAsync(ct); return Result.Ok(new IdentityRolePageDto<IdentityRoleListItemDto>(rows.Select(r=>new IdentityRoleListItemDto(r.Id,r.Name!,IsProtected(r.Name!),r.Count)).ToList(),total,pageNumber,pageSize)); }
    public async Task<Result<IdentityRoleDetailDto>> GetRoleAsync(string roleId,CancellationToken ct)
    { var row=await _context.Roles.AsNoTracking().Where(r=>r.Id==roleId).Select(r=>new {r.Id,r.Name,r.ConcurrencyStamp,Count=_context.UserRoles.Count(x=>x.RoleId==r.Id)}).SingleOrDefaultAsync(ct); return row is null ? NotFound<IdentityRoleDetailDto>() : Result.Ok(new IdentityRoleDetailDto(row.Id,row.Name!,IsProtected(row.Name!),row.Count,Tag(row.Id,row.ConcurrencyStamp))); }
    public async Task<Result<IdentityRoleDetailDto>> CreateRoleAsync(string actor,string? proof,string name,CancellationToken ct)
    { var auth=await AuthorizeAsync(actor,proof,ct); if(auth.IsFailed)return Result.Fail<IdentityRoleDetailDto>(auth.Errors); var valid=ValidateName(name); if(valid is not null)return Fail<IdentityRoleDetailDto>("Validation",valid); if(IsProtected(name)) return Fail<IdentityRoleDetailDto>("Conflict","Reserved role name."); var role=new IdentityRole(name.Trim()); var result=await _roles.CreateAsync(role); if(!result.Succeeded)return Fail<IdentityRoleDetailDto>("Conflict","Role name already exists or is invalid."); return await GetRoleAsync(role.Id,ct); }
    public async Task<Result<IdentityRoleDetailDto>> RenameRoleAsync(string actor,string? proof,string roleId,string? etag,string name,CancellationToken ct)
    { var auth=await AuthorizeAsync(actor,proof,ct); if(auth.IsFailed)return Result.Fail<IdentityRoleDetailDto>(auth.Errors); if(string.IsNullOrWhiteSpace(etag))return Fail<IdentityRoleDetailDto>("PreconditionRequired","If-Match is required."); var valid=ValidateName(name); if(valid is not null)return Fail<IdentityRoleDetailDto>("Validation",valid); await using var tx=await _context.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct); try { var role=await _context.Roles.SingleOrDefaultAsync(r=>r.Id==roleId,ct); if(role is null)return NotFound<IdentityRoleDetailDto>(); if(!string.Equals(etag,Tag(role.Id,role.ConcurrencyStamp),StringComparison.Ordinal))return Fail<IdentityRoleDetailDto>("PreconditionFailed","The role has changed."); if(IsProtected(role.Name!))return Fail<IdentityRoleDetailDto>("Conflict","Protected roles cannot be renamed."); if(string.Equals(role.Name,name.Trim(),StringComparison.Ordinal)) { await tx.CommitAsync(ct); return await GetRoleAsync(roleId,ct); } role.Name=name.Trim(); var update=await _roles.UpdateAsync(role); if(!update.Succeeded)return Fail<IdentityRoleDetailDto>("Conflict","Role name already exists or has changed."); var ids=await _context.UserRoles.Where(x=>x.RoleId==role.Id).Select(x=>x.UserId).ToListAsync(ct); foreach(var id in ids){var u=await _users.FindByIdAsync(id);if(u is null || !(await _tokens.InvalidateAsync(u,ct)).Succeeded)throw new InvalidOperationException();} await tx.CommitAsync(ct); return await GetRoleAsync(roleId,ct); } catch(DbUpdateConcurrencyException){await tx.RollbackAsync(CancellationToken.None);return Fail<IdentityRoleDetailDto>("PreconditionFailed","The role has changed.");} catch {await tx.RollbackAsync(CancellationToken.None);return Fail<IdentityRoleDetailDto>("OperationalFailure","Unable to update role.");} }
    public async Task<Result> DeleteRoleAsync(string actor,string? proof,string roleId,CancellationToken ct)
    { var auth=await AuthorizeAsync(actor,proof,ct);if(auth.IsFailed)return auth; await using var tx=await _context.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct); try {var role=await _context.Roles.SingleOrDefaultAsync(r=>r.Id==roleId,ct);if(role is null)return NotFound();if(IsProtected(role.Name!))return Fail("Conflict","Protected roles cannot be deleted.");if(await _context.UserRoles.AnyAsync(x=>x.RoleId==roleId,ct))return Fail("Conflict","Assigned roles cannot be deleted.");var r=await _roles.DeleteAsync(role);if(!r.Succeeded)return Fail("Conflict","Unable to delete role.");await tx.CommitAsync(ct);return Result.Ok();}catch{await tx.RollbackAsync(CancellationToken.None);return Fail("OperationalFailure","Unable to delete role.");}}
    public async Task<Result<IReadOnlyList<IdentityRoleAssignmentDto>>> GetUserRolesAsync(string userId,CancellationToken ct)
    {if(!await _context.Users.AsNoTracking().AnyAsync(u=>u.Id==userId,ct))return NotFound<IReadOnlyList<IdentityRoleAssignmentDto>>(); var rows=await (from ur in _context.UserRoles.AsNoTracking() join r in _context.Roles.AsNoTracking() on ur.RoleId equals r.Id where ur.UserId==userId orderby r.NormalizedName,r.Id select new IdentityRoleAssignmentDto(r.Id,r.Name!,IsProtected(r.Name!))).ToListAsync(ct);return Result.Ok<IReadOnlyList<IdentityRoleAssignmentDto>>(rows);}
    public async Task<Result> ReplaceUserRolesAsync(string actor,string? proof,string userId,IReadOnlyCollection<string>? roleIds,CancellationToken ct)
    {var auth=await AuthorizeAsync(actor,proof,ct);if(auth.IsFailed)return auth;if(actor==userId)return Fail("Validation","Administrators cannot change their own roles.");var desired=roleIds?.ToList()??[];if(desired.Count>100||desired.Any(string.IsNullOrWhiteSpace)||desired.Distinct(StringComparer.Ordinal).Count()!=desired.Count)return Fail("Validation","Role IDs must be unique and limited to 100.");await using var tx=await _context.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var user=await _users.FindByIdAsync(userId);if(user is null)return NotFound();if(!await _tokens.IsEligibleAsync(user,_restrictions,ct))return Fail("Validation","Target is not eligible.");var roles=await _context.Roles.Where(r=>desired.Contains(r.Id)).ToListAsync(ct);if(roles.Count!=desired.Count)return Fail("Validation","One or more roles do not exist.");var current=await _context.UserRoles.Where(x=>x.UserId==userId).Select(x=>x.RoleId).ToListAsync(ct);var add=roles.Where(r=>!current.Contains(r.Id)).ToList();var remove=current.Where(id=>!desired.Contains(id)).ToList();if(add.Count==0&&remove.Count==0){await tx.CommitAsync(ct);return Result.Ok();}var superId=await _context.Roles.Where(r=>r.NormalizedName==_normalizer.NormalizeName(IdentityRoleNames.Superadmin)).Select(r=>r.Id).SingleAsync(ct);if(current.Contains(superId)&&!desired.Contains(superId)){var admins=await (from ur in _context.UserRoles join u in _context.Users on ur.UserId equals u.Id where ur.RoleId==superId select u).ToListAsync(ct);var effective=0;foreach(var admin in admins)if(_tokens.IsEligible(admin)&&await _restrictions.IsAuthenticationAllowedAsync(admin,ct))effective++;if(effective<=1)return Fail("Conflict","The last effective Superadmin cannot be removed.");}foreach(var r in add){var result=await _users.AddToRoleAsync(user,r.Name!);if(!result.Succeeded)throw new InvalidOperationException();}foreach(var id in remove){var role=await _context.Roles.SingleAsync(r=>r.Id==id,ct);var result=await _users.RemoveFromRoleAsync(user,role.Name!);if(!result.Succeeded)throw new InvalidOperationException();}if(!(await _tokens.InvalidateAsync(user,ct)).Succeeded)throw new InvalidOperationException();await tx.CommitAsync(ct);return Result.Ok();}catch{await tx.RollbackAsync(CancellationToken.None);return Fail("OperationalFailure","Unable to update roles.");}}
    public async Task<Result<IdentityRolePageDto<IdentityRoleUserDto>>> GetRoleUsersAsync(string roleId,int pageNumber,int pageSize,CancellationToken ct){if(!await _context.Roles.AsNoTracking().AnyAsync(r=>r.Id==roleId,ct))return NotFound<IdentityRolePageDto<IdentityRoleUserDto>>();var q=from ur in _context.UserRoles.AsNoTracking() join u in _context.Users.AsNoTracking() on ur.UserId equals u.Id where ur.RoleId==roleId orderby u.Id select new IdentityRoleUserDto(u.Id,u.UserName!);var total=await q.CountAsync(ct);return Result.Ok(new IdentityRolePageDto<IdentityRoleUserDto>(await q.Skip((pageNumber-1)*pageSize).Take(pageSize).ToListAsync(ct),total,pageNumber,pageSize));}
    private async Task<Result> AuthorizeAsync(string actor,string? proof,CancellationToken ct){var user=await _users.FindByIdAsync(actor);if(user is null||!await _proof.IsValidAsync(actor,proof,ct)||!await _users.IsInRoleAsync(user,IdentityRoleNames.Superadmin))return Fail("Validation","Unable to authorize role change.");return Result.Ok();}
    private static bool IsProtected(string name)=>ProtectedRoles.Contains(name,StringComparer.OrdinalIgnoreCase); private static string? ValidateName(string n){n=n?.Trim()??"";return n.Length is <1 or >64||!n.All(c=>char.IsLetterOrDigit(c)||c==' '||c=='-'||c=='_')?"Role name is invalid.":null;} private static string Tag(string id,string? stamp)=>"\""+Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(id+"|"+stamp)))+"\""; private static Result Fail(string k,string m)=>Result.Fail(new Error(m).WithMetadata(k,true)); private static Result<T> Fail<T>(string k,string m)=>Result.Fail<T>(new Error(m).WithMetadata(k,true)); private static Result NotFound()=>Fail("NotFound","Role or user was not found.");private static Result<T> NotFound<T>()=>Fail<T>("NotFound","Role or user was not found.");
}

internal static class RoleManagementTokenExtensions { public static Task<bool> IsEligibleAsync(this IIdentityTokenStateService tokens, ApplicationUser user, IIdentityRestrictionService restrictions, CancellationToken ct) => IsEligible(tokens,user,restrictions,ct); private static async Task<bool> IsEligible(IIdentityTokenStateService tokens, ApplicationUser user,IIdentityRestrictionService restrictions,CancellationToken ct) => tokens.IsEligible(user)&&await restrictions.IsAuthenticationAllowedAsync(user,ct); }
